export type MethodParamsMap = { [M in Request["method"]]: Extract<Request, { method: M }> extends { params: infer P } ? P : undefined };
export type MethodMap = { [M in keyof MethodResultMap]: { params: M extends keyof MethodParamsMap ? MethodParamsMap[M] : never; result: MethodResultMap[M] } };
export type NotificationMap = { [M in Notification["method"]]: Extract<Notification, { method: M }>["params"] };
